using System.Text.Json;
using Ff7.Accessibility.LegacyLayout;

namespace Ff7.Accessibility.Reloaded;

/// <summary>
/// Exact stock and current official Echo-S 1.24 native prefix identities. This contains
/// fingerprints and reviewed metadata, never licensed scripts or fuzzy runtime matching.
/// Regenerate from the retained range/header/SHA evidence with generate_navigation_manifest.py.
/// </summary>
public static class WholeGameEchoNavigationManifest
{
    public const int SchemaVersion = 1;
    public const string Source = "https://gp-mc.net/tsunamods/echo-s-7/latest_full/Echo-s.iro";
    private static readonly IReadOnlyDictionary<int, Layout> Layouts = ReadLayouts();

    public static bool SourceKnownExactPrefixHash(int fieldId, string hash) =>
        ResolveVariant(new LoadedFieldScriptIdentity(fieldId, hash)) != SupportedFieldScriptVariant.Unknown;

    public static SupportedFieldScriptVariant ResolveVariant(LoadedFieldScriptIdentity identity)
    {
        if (PostscriptFieldCompatibility.IsSupportedOpeningIdentity(identity))
            return SupportedFieldScriptVariant.Postscript178;
        if (!Layouts.TryGetValue(identity.FieldId, out var row)) return SupportedFieldScriptVariant.Unknown;
        if (row.OfficialStock.Contains(identity.ScriptPrefixSha256, StringComparer.OrdinalIgnoreCase)) return SupportedFieldScriptVariant.Vanilla;
        return row.Echo.Contains(identity.ScriptPrefixSha256, StringComparer.OrdinalIgnoreCase)
            ? SupportedFieldScriptVariant.EchoS124 : SupportedFieldScriptVariant.Unknown;
    }

    // The English cue catalog uses English byte offsets. Official localized navigation
    // identities do not authorize those action anchors without a separate cue audit.
    public static SupportedFieldScriptVariant ResolveDescriptionVariant(LoadedFieldScriptIdentity identity)
    {
        if (PostscriptFieldCompatibility.IsSupportedOpeningIdentity(identity))
            return SupportedFieldScriptVariant.Postscript178;
        if (!Layouts.TryGetValue(identity.FieldId, out var row)) return SupportedFieldScriptVariant.Unknown;
        if (string.Equals(identity.ScriptPrefixSha256, row.Stock, StringComparison.OrdinalIgnoreCase)) return SupportedFieldScriptVariant.Vanilla;
        return row.Echo.Contains(identity.ScriptPrefixSha256, StringComparer.OrdinalIgnoreCase)
            ? SupportedFieldScriptVariant.EchoS124 : SupportedFieldScriptVariant.Unknown;
    }

    internal static IReadOnlyDictionary<int, int> EntityMap(int fieldId) => Layouts[fieldId].Map;
    internal static IReadOnlyDictionary<int,int>? ReviewedOfficialStockEntityMap(LoadedFieldScriptIdentity identity) =>
        Layouts.TryGetValue(identity.FieldId, out var row) && row.OfficialStockEntityMaps.TryGetValue(identity.ScriptPrefixSha256.ToUpperInvariant(), out var mapping) ? mapping : null;
    internal static IReadOnlyDictionary<int,string> NpcLabels(int fieldId) => Layouts[fieldId].NpcLabels;
    internal static IReadOnlyList<string>? Models(int fieldId) => Layouts[fieldId].Models;
    internal static string? StockFingerprint(int fieldId) => Layouts.TryGetValue(fieldId, out var row) ? row.Stock : null;
    internal static string? EchoFingerprint(int fieldId) => Layouts.TryGetValue(fieldId, out var row) ? row.Echo[0] : null;

    private static IReadOnlyDictionary<int, Layout> ReadLayouts()
    {
        var rows = new Dictionary<int, Layout>();
        foreach (var line in RawLayouts.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var row = JsonSerializer.Deserialize<Layout>(line) ?? throw new InvalidOperationException("Missing reviewed native layout");
            bool Hash(string value) => value.Length == 64 && value.All(Uri.IsHexDigit);
            if (!Hash(row.Stock) || row.OfficialStock.Length == 0 || row.OfficialStock.Any(h => !Hash(h)) || !row.OfficialStock.Contains(row.Stock) || row.Echo.Length == 0 || row.Echo.Any(h => !Hash(h)) ||
                row.Map.Keys.Any(k => k < 0 || k > 255) || row.Map.Values.Any(k => k < 0 || k > 255) ||
                row.Map.Values.Distinct().Count() != row.Map.Count || row.OfficialStockEntityMaps.Any(p => !row.OfficialStock.Contains(p.Key) || p.Value.Values.Distinct().Count() != p.Value.Count) || row.NpcLabels.Any(p => p.Key < 0 || p.Key > 255 || string.IsNullOrWhiteSpace(p.Value)) || !rows.TryAdd(row.Field, row))
                throw new InvalidOperationException($"Invalid reviewed native layout field {row.Field}");
        }
        if (rows.Count != 702) throw new InvalidOperationException("Incomplete reviewed native field manifest");
        return rows;
    }

    private sealed record Layout(int Field, string Stock, string[] OfficialStock, string[] Echo, Dictionary<int, int> Map, string[]? Models, Dictionary<int,string> NpcLabels, Dictionary<string,Dictionary<int,int>> OfficialStockEntityMaps);

    // Native SHA evidence: 8bc7b6d90f5e079a453a8828d642c34bebb1a65c83b725982795dcc16838f50e. All five variants have identical
